#include <vector>
#include <map>
#include <algorithm>

using namespace std;

class Solution {
public:
    int maxProduct(vector<int>& nums, int k, int limit) {
        map<pair<int, int>, int> dp;
        for (int x : nums) {
            auto nextDp = dp;
            if (x <= limit) {
                nextDp[{x, 1}] = max(nextDp[{x, 1}], x);
            }
            for (const auto& [st, prod] : dp) {
                long long np = (long long)prod * x;
                if (np <= limit) {
                    int ns = (st.second == 0) ? (st.first + x) : (st.first - x);
                    int nextPar = 1 - st.second;
                    nextDp[{ns, nextPar}] = max(nextDp[{ns, nextPar}], (int)np);
                }
            }
            dp = std::move(nextDp);
        }
        int ans = -1;
        if (dp.count({k, 0})) ans = max(ans, dp[{k, 0}]);
        if (dp.count({k, 1})) ans = max(ans, dp[{k, 1}]);
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxProduct(int[] nums, int k, int limit) {
        Map<String, Integer> dp = new HashMap<>();
        for (int x : nums) {
            Map<String, Integer> nextDp = new HashMap<>(dp);
            if (x <= limit) {
                String key = x + ",1";
                nextDp.put(key, Math.max(nextDp.getOrDefault(key, -1), x));
            }
            for (Map.Entry<String, Integer> entry : dp.entrySet()) {
                String[] parts = entry.getKey().split(",");
                int s = Integer.parseInt(parts[0]);
                int par = Integer.parseInt(parts[1]);
                long np = (long) entry.getValue() * x;
                if (np <= limit) {
                    int ns = (par == 0) ? (s + x) : (s - x);
                    int nextPar = 1 - par;
                    String nKey = ns + "," + nextPar;
                    nextDp.put(nKey, Math.max(nextDp.getOrDefault(nKey, -1), (int) np));
                }
            }
            dp = nextDp;
        }
        int ans = -1;
        ans = Math.max(ans, dp.getOrDefault(k + ",0", -1));
        ans = Math.max(ans, dp.getOrDefault(k + ",1", -1));
        return ans;
    }
}

var maxProduct = function(nums, k, limit) {
    let dp = new Map();
    for (const x of nums) {
        const nextDp = new Map(dp);
        if (x <= limit) {
            const key = `${x},1`;
            nextDp.set(key, Math.max(nextDp.get(key) || -1, x));
        }
        for (const [key, prod] of dp.entries()) {
            const [sStr, parStr] = key.split(',');
            const s = Number(sStr);
            const par = Number(parStr);
            const np = prod * x;
            if (np <= limit) {
                const ns = par === 0 ? s + x : s - x;
                const nextPar = 1 - par;
                const nKey = `${ns},${nextPar}`;
                nextDp.set(nKey, Math.max(nextDp.get(nKey) || -1, np));
            }
        }
        dp = nextDp;
    }
    const a0 = dp.get(`${k},0`) ?? -1;
    const a1 = dp.get(`${k},1`) ?? -1;
    return Math.max(a0, a1);
};
